    if not text:
        return {}, ""

    lines = text.split('\n')
    if lines[0] != '---':
        return {}, text

    metadata = {}
    content_lines = []
    i = 1
    n = len(lines)

    while i < n and lines[i] != '---':
        line = lines[i].strip()
        if ':' in line:
            key, value = line.split(':', 1)
            metadata[key.strip()] = value.strip()
        i += 1

    if i >= n or lines[i] != '---':
        return {}, text

    content_lines = lines[i+1:]
    remaining_content = '\n'.join(content_lines)

    return metadata, remaining_content
